import { Component, OnInit } from '@angular/core';
import { CharacterService } from "../../service/character.service";
import { Characters } from "../../model/characters";
import { Character } from "../../model/character";

@Component({
  selector: 'app-character-list',
  templateUrl: './character-list.component.html',
  styleUrls: ['./character-list.component.css']
})
export class CharacterListComponent implements OnInit{

  /**
   * @param service characters service
   */
  constructor(private service: CharacterService) {
  }

  /**
   * Available characters.
   */
  characters: Characters | undefined;

  ngOnInit(): void {
    this.service.getCharacters().subscribe(characters => this.characters = characters);
  }

  /**
   * Deletes selected character.
   *
   * @param user character to be removed
   */
  onDelete(character: Character): void {
    this.service.deleteCharacter(character.id).subscribe(() => this.ngOnInit());
  }

}
<article class="text--justified">
  <header><h2>Characters</h2></header>

  <table *ngIf="characters">
    <thead>
      <tr>
        <th>Portrait</th>
        <th>Name</th>
        <th>View</th>
        <th>Edit</th>
        <th>Delete</th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let character of characters.characters">
        <td>
          <img class="portrait" alt="Character portrait" src="/api/characters/{{character.id}}/portrait"/>
        </td>
        <td>{{character.name}}</td>
        <td>
          <a [routerLink]="['/characters', character.id]">View</a>
        </td>
        <td>
          <a [routerLink]="['/characters', character.id, 'edit']">Edit</a>
        </td>
        <td>
          <button (click)="onDelete(character)">Delete</button>
        </td>
      </tr>
    </tbody>
  </table>
</article>
